static const wchar_t *leaf(const wchar_t *p){const wchar_t *v=wcsrchr(p,L'\\');return v?v+1:p;}
static void parentpath(wchar_t *out,const wchar_t *p){wcsncpy(out,p,PCAP-1);out[PCAP-1]=0;wchar_t *v=wcsrchr(out,L'\\');if(v&&v>out+2)*v=0;else if(v)v[1]=0;}
static void disabledroot(wchar_t *out){wchar_t p[PCAP];parentpath(p,cfg.community);pathjoin(out,p,L"AeroSim-Disabled");}
static int inpath(const wchar_t *p,const wchar_t *root){size_t n=wcslen(root);return n&&_wcsnicmp(p,root,n)==0&&(p[n]==0||p[n]==L'\\');}
static COLORREF blend(COLORREF a,COLORREF b,double t){return RGB((int)(GetRValue(a)*(1-t)+GetRValue(b)*t),(int)(GetGValue(a)*(1-t)+GetGValue(b)*t),(int)(GetBValue(a)*(1-t)+GetBValue(b)*t));}
static double luminance(COLORREF c){double v[3]={GetRValue(c)/255.0,GetGValue(c)/255.0,GetBValue(c)/255.0};for(int i=0;i<3;i++)v[i]=v[i]<=.04045?v[i]/12.92:pow((v[i]+.055)/1.055,2.4);return v[0]*.2126+v[1]*.7152+v[2]*.0722;}
static double contrast(COLORREF a,COLORREF b){double x=luminance(a),y=luminance(b);return x>y?(x+.05)/(y+.05):(y+.05)/(x+.05);}
static COLORREF readable(COLORREF color,COLORREF surface){COLORREF target=contrast(RGB(255,255,255),surface)>=contrast(RGB(0,0,0),surface)?RGB(255,255,255):RGB(0,0,0);for(int i=0;i<=100;i++){COLORREF v=blend(color,target,i/100.0);if(contrast(v,surface)>=4.5)return v;}return target;}
static COLORREF accentink(void){return contrast(RGB(255,255,255),cfg.accent)>=contrast(RGB(14,20,30),cfg.accent)?RGB(255,255,255):RGB(14,20,30);}
