static void logline(const wchar_t *s){FILE *f=_wfopen(logpath,L"ab");if(!f)return;SYSTEMTIME t;GetLocalTime(&t);char u[10000];wchar_t v[4096];swprintf(v,4096,L"%04d-%02d-%02d %02d:%02d:%02d  %ls\r\n",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond,s);int n=WideCharToMultiByte(CP_UTF8,0,v,-1,u,sizeof(u),NULL,NULL);if(n>1)fwrite(u,1,n-1,f);fclose(f);}
