static int maxscroll(void){int count=ListView_GetItemCount(list),visible=ListView_GetCountPerPage(list);if(visible<1)visible=1;return count>visible?count-visible:0;}
static void scrollto(int top){int max=maxscroll();if(top<0)top=0;if(top>max)top=max;int before=ListView_GetTopIndex(list);if(top!=before)ListView_Scroll(list,0,(top-before)*rowheight());updatescroll();}
