static void drawbutton(DRAWITEMSTRUCT *d){
 int id=(int)d->CtlID,disabled=!!(d->itemState&ODS_DISABLED),pressed=!!(d->itemState&ODS_SELECTED);
 int primary=id==ID_NEXT||id==ID_IMPORT_FOLDER||id==ID_TOGGLE||id==ID_SAVE;
 int nav=id>=ID_HOME&&id<=ID_MODS;
 int chosen=(id==ID_HOME&&page==0)||(id==ID_MODS&&page==4)||(id==ID_FAVORITES&&page==1)||(id==ID_SETTINGS&&page==2)||(id==ID_GUIDE&&page==3);
 double over=id>=0&&id<200&&!disabled?buttonHover[id]:0;
 COLORREF c=primary?cfg.accent:nav?(chosen?blend(side,cfg.accent,.13):side):control;
 if(id==ID_BLUE)c=RGB(0,112,245);if(id==ID_PURPLE)c=RGB(128,75,215);if(id==ID_MINT)c=RGB(0,128,100);
 COLORREF ink=primary?accentink():((id==ID_BLUE||id==ID_PURPLE||id==ID_MINT)?RGB(255,255,255):text);
 if(disabled){c=blend(c,bg,.55);ink=blend(ink,bg,.6);}else if(pressed)c=blend(c,ink,.14);else c=blend(c,nav?cfg.accent:ink,(nav?.12:.09)*over);
 COLORREF under=nav?side:setup>=0?card:page==2||page==3?card:((page==4||page==1)&&(id==ID_IMPORT_FOLDER||id==ID_IMPORT_ZIP))?soft:bg;
 HBRUSH surround=CreateSolidBrush(under);FillRect(d->hDC,&d->rcItem,surround);DeleteObject(surround);
 RECT face=d->rcItem;int inset=pressed?2:(over<.55?1:0);if(nav)inset=0;InflateRect(&face,-inset,-inset);box(d->hDC,face,c,12);
 if(over>.01&&!disabled&&!nav){HPEN p=CreatePen(PS_SOLID,1,blend(c,primary?ink:accentText,.22*over));HGDIOBJ old=SelectObject(d->hDC,p),brush=SelectObject(d->hDC,GetStockObject(NULL_BRUSH));RoundRect(d->hDC,face.left,face.top,face.right,face.bottom,12,12);SelectObject(d->hDC,old);SelectObject(d->hDC,brush);DeleteObject(p);}
 if(nav&&chosen){RECT bar={face.left+3,face.top+11,face.left+6,face.bottom-11};box(d->hDC,bar,accentText,3);}
 wchar_t caption[256];GetWindowTextW(d->hwndItem,caption,256);RECT r=face;
 if(nav){r.left+=13+(int)(3*over+.5);txt(d->hDC,caption,r,fBody,chosen?accentText:ink,DT_LEFT|DT_VCENTER|DT_SINGLELINE);}else{if(!pressed)OffsetRect(&r,0,-(int)(over+.2));txt(d->hDC,caption,r,fBody,ink,DT_CENTER|DT_VCENTER|DT_SINGLELINE);}
 if((d->itemState&ODS_FOCUS)&&keyboardFocus&&!disabled){RECT focus=face;InflateRect(&focus,-3,-3);HPEN p=CreatePen(PS_SOLID,1,primary?ink:accentText);HGDIOBJ old=SelectObject(d->hDC,p),brush=SelectObject(d->hDC,GetStockObject(NULL_BRUSH));RoundRect(d->hDC,focus.left,focus.top,focus.right,focus.bottom,10,10);SelectObject(d->hDC,old);SelectObject(d->hDC,brush);DeleteObject(p);}
}
static void bufferedbutton(DRAWITEMSTRUCT *d){int width=d->rcItem.right-d->rcItem.left,height=d->rcItem.bottom-d->rcItem.top;if(width<=0||height<=0)return;HDC memory=CreateCompatibleDC(d->hDC);HBITMAP bmp=CreateCompatibleBitmap(d->hDC,width,height);if(!memory||!bmp){if(memory)DeleteDC(memory);if(bmp)DeleteObject(bmp);drawbutton(d);return;}HGDIOBJ old=SelectObject(memory,bmp);DRAWITEMSTRUCT copy=*d;copy.hDC=memory;copy.rcItem=(RECT){0,0,width,height};drawbutton(&copy);BitBlt(d->hDC,d->rcItem.left,d->rcItem.top,width,height,memory,0,0,SRCCOPY);SelectObject(memory,old);DeleteObject(bmp);DeleteDC(memory);}
